#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>

struct TrieNode {
    int next[26];
    int id;
    TrieNode() {
        std::fill(next, next + 26, -1);
        id = -1;
    }
};

class Solution {
public:
    long long minimumCost(std::string source, std::string target, std::vector<std::string>& original, std::vector<std::string>& changed, std::vector<int>& cost) {
        std::unordered_map<std::string, int> wordId;
        auto getId = [&](const std::string& s) {
            if (!wordId.count(s)) {
                int id = wordId.size();
                wordId[s] = id;
            }
            return wordId[s];
        };
        for (const auto& s : original) getId(s);
        for (const auto& s : changed) getId(s);

        int m = wordId.size();
        const long long INF = 1e16;
        std::vector<std::vector<long long>> dist(m, std::vector<long long>(m, INF));
        for (int i = 0; i < m; ++i) dist[i][i] = 0;
        for (size_t i = 0; i < original.size(); ++i) {
            int u = wordId[original[i]];
            int v = wordId[changed[i]];
            dist[u][v] = std::min(dist[u][v], (long long)cost[i]);
        }
        for (int k = 0; k < m; ++k) {
            for (int i = 0; i < m; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (dist[i][k] + dist[k][j] < dist[i][j]) {
                        dist[i][j] = dist[i][k] + dist[k][j];
                    }
                }
            }
        }

        std::vector<TrieNode> trie(1);
        for (const auto& p : wordId) {
            int curr = 0;
            for (char ch : p.first) {
                int c = ch - 'a';
                if (trie[curr].next[c] == -1) {
                    trie[curr].next[c] = trie.size();
                    trie.emplace_back();
                }
                curr = trie[curr].next[c];
            }
            trie[curr].id = p.second;
        }

        int n = source.size();
        std::vector<long long> dp(n + 1, INF);
        dp[0] = 0;
        for (int i = 0; i < n; ++i) {
            if (dp[i] >= INF) continue;
            if (source[i] == target[i]) {
                dp[i + 1] = std::min(dp[i + 1], dp[i]);
            }
            int uNode = 0, vNode = 0;
            for (int j = i; j < n; ++j) {
                int cU = source[j] - 'a';
                int cV = target[j] - 'a';
                if (trie[uNode].next[cU] == -1 || trie[vNode].next[cV] == -1) break;
                uNode = trie[uNode].next[cU];
                vNode = trie[vNode].next[cV];
                if (trie[uNode].id != -1 && trie[vNode].id != -1) {
                    int uid = trie[uNode].id;
                    int vid = trie[vNode].id;
                    if (dist[uid][vid] < INF) {
                        dp[j + 1] = std::min(dp[j + 1], dp[i] + dist[uid][vid]);
                    }
                }
            }
        }
        return dp[n] >= INF ? -1 : dp[n];
    }
};

import java.util.*;

class Solution {
    static class TrieNode {
        int[] next = new int[26];
        int id = -1;
        TrieNode() {
            Arrays.fill(next, -1);
        }
    }

    public long minimumCost(String source, String target, String[] original, String[] changed, int[] cost) {
        Map<String, Integer> wordId = new HashMap<>();
        for (String s : original) {
            if (!wordId.containsKey(s)) wordId.put(s, wordId.size());
        }
        for (String s : changed) {
            if (!wordId.containsKey(s)) wordId.put(s, wordId.size());
        }

        int m = wordId.size();
        long INF = (long) 1e16;
        long[][] dist = new long[m][m];
        for (int i = 0; i < m; i++) {
            Arrays.fill(dist[i], INF);
            dist[i][i] = 0;
        }
        for (int i = 0; i < original.length; i++) {
            int u = wordId.get(original[i]);
            int v = wordId.get(changed[i]);
            dist[u][v] = Math.min(dist[u][v], cost[i]);
        }
        for (int k = 0; k < m; k++) {
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < m; j++) {
                    if (dist[i][k] + dist[k][j] < dist[i][j]) {
                        dist[i][j] = dist[i][k] + dist[k][j];
                    }
                }
            }
        }

        List<TrieNode> trie = new ArrayList<>();
        trie.add(new TrieNode());
        for (Map.Entry<String, Integer> entry : wordId.entrySet()) {
            int curr = 0;
            for (char ch : entry.getKey().toCharArray()) {
                int c = ch - 'a';
                if (trie.get(curr).next[c] == -1) {
                    trie.get(curr).next[c] = trie.size();
                    trie.add(new TrieNode());
                }
                curr = trie.get(curr).next[c];
            }
            trie.get(curr).id = entry.getValue();
        }

        int n = source.length();
        long[] dp = new long[n + 1];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int i = 0; i < n; i++) {
            if (dp[i] >= INF) continue;
            if (source.charAt(i) == target.charAt(i)) {
                dp[i + 1] = Math.min(dp[i + 1], dp[i]);
            }
            int uNode = 0, vNode = 0;
            for (int j = i; j < n; j++) {
                int cU = source.charAt(j) - 'a';
                int cV = target.charAt(j) - 'a';
                if (trie.get(uNode).next[cU] == -1 || trie.get(vNode).next[cV] == -1) break;
                uNode = trie.get(uNode).next[cU];
                vNode = trie.get(vNode).next[cV];
                if (trie.get(uNode).id != -1 && trie.get(vNode).id != -1) {
                    int uid = trie.get(uNode).id;
                    int vid = trie.get(vNode).id;
                    if (dist[uid][vid] < INF) {
                        dp[j + 1] = Math.min(dp[j + 1], dp[i] + dist[uid][vid]);
                    }
                }
            }
        }
        return dp[n] >= INF ? -1 : dp[n];
    }
}

var minimumCost = function(source, target, original, changed, cost) {
    const wordId = new Map();
    for (const w of [...original, ...changed]) {
        if (!wordId.has(w)) {
            wordId.set(w, wordId.size);
        }
    }
    const m = wordId.size;
    const INF = Infinity;
    const dist = Array.from({ length: m }, () => new Array(m).fill(INF));
    for (let i = 0; i < m; i++) dist[i][i] = 0;
    for (let i = 0; i < original.length; i++) {
        const u = wordId.get(original[i]);
        const v = wordId.get(changed[i]);
        dist[u][v] = Math.min(dist[u][v], cost[i]);
    }
    for (let k = 0; k < m; k++) {
        for (let i = 0; i < m; i++) {
            for (let j = 0; j < m; j++) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
    }
    const root = {};
    for (const [w, wid] of wordId.entries()) {
        let node = root;
        for (const ch of w) {
            if (!node[ch]) node[ch] = {};
            node = node[ch];
        }
        node['#'] = wid;
    }
    const n = source.length;
    const dp = new Array(n + 1).fill(INF);
    dp[0] = 0;
    for (let i = 0; i < n; i++) {
        if (dp[i] === INF) continue;
        if (source[i] === target[i]) {
            dp[i + 1] = Math.min(dp[i + 1], dp[i]);
        }
        let uNode = root, vNode = root;
        for (let j = i; j < n; j++) {
            if (!uNode[source[j]] || !vNode[target[j]]) break;
            uNode = uNode[source[j]];
            vNode = vNode[target[j]];
            if ('#' in uNode && '#' in vNode) {
                const uid = uNode['#'];
                const vid = vNode['#'];
                if (dist[uid][vid] < INF) {
                    dp[j + 1] = Math.min(dp[j + 1], dp[i] + dist[uid][vid]);
                }
            }
        }
    }
    return dp[n] === INF ? -1 : dp[n];
};
